DELETE FROM Language_en_US WHERE Tag='TXT_KEY_CWC2_GUIDE_KINGDOMOFSABA' OR Tag GLOB 'TXT_KEY_CWC2_GUIDE_KINGDOMOFSABA_*';
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC2_GUIDE_KINGDOMOFSABA_CIV_HEADING_1','Playstyle and victory plan');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC2_GUIDE_KINGDOMOFSABA_CIV_TEXT_1','Saba[NEWLINE]Low-management River settlement and practical early defense[NEWLINE]Science or Culture through population and conventional infrastructure[NEWLINE][NEWLINE]Choose productive River sites and take the Desert city-centre bonus where the surrounding land can still feed the city. The ability rewards a good settlement, not every city placed beside a visible patch of sand.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC2_GUIDE_KINGDOMOFSABA_CIV_HEADING_2','Opening priorities');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC2_GUIDE_KINGDOMOFSABA_CIV_TEXT_2','Scout rivers and the actual city-centre terrain. Prioritize enough food, production and resources over a nominal Desert bonus. Wadi Sentinels help watch and defend suitable dry approaches.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC2_GUIDE_KINGDOMOFSABA_CIV_HEADING_3','Develop the engine');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC2_GUIDE_KINGDOMOFSABA_CIV_TEXT_3','Build Cisterns where the active Water Mill requirements permit them. Turn the added food and Gold into citizens, research infrastructure and a workable treasury. Further expansion should be justified by the full site quality.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC2_GUIDE_KINGDOMOFSABA_CIV_HEADING_4','Convert the advantage');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC2_GUIDE_KINGDOMOFSABA_CIV_TEXT_4','Use the developed population and ordinary science or cultural programme to finish the game. Upgrade defenses when needed; the Sentinel''s specific Desert-defense and Sight additions do not continue through its upgrade.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC2_GUIDE_KINGDOMOFSABA_CIV_HEADING_5','Strengths');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC2_GUIDE_KINGDOMOFSABA_CIV_TEXT_5','- Useful settlement bonuses operate automatically without a custom action cycle.[NEWLINE]- River and Desert-centre conditions can stack.[NEWLINE]- Cisterns improve an ordinary food-and-Gold development plan.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC2_GUIDE_KINGDOMOFSABA_CIV_HEADING_6','Weaknesses and costs');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC2_GUIDE_KINGDOMOFSABA_CIV_TEXT_6','- The signature yields depend on the actual city centre and River status.[NEWLINE]- There is no direct Science or Tourism bonus.[NEWLINE]- The Sentinel''s unique bonuses are temporary to that unit type and are not an attacking boost.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC2_GUIDE_KINGDOMOFSABA_CIV_HEADING_7','How to play against this civilization');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC2_GUIDE_KINGDOMOFSABA_CIV_TEXT_7','- Contest the strongest River sites and productive desert approaches.[NEWLINE]- Fight away from the Sentinel''s preferred defending terrain.[NEWLINE]- Pressure a weak-food settlement whose owner chased the Desert label at the expense of development.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC2_GUIDE_KINGDOMOFSABA_CIV_HEADING_8','Common mistakes');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC2_GUIDE_KINGDOMOFSABA_CIV_TEXT_8','- Counting adjacent Desert or an Oasis as the required city-centre/River condition.[NEWLINE]- Assuming a Cistern ignores normal Water Mill prerequisites.[NEWLINE]- Expecting the unique defensive promotion to make a strong offensive army or survive upgrading.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC2_GUIDE_KINGDOMOFSABA_CIV_HEADING_9','Matchup examples - conditional analysis');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC2_GUIDE_KINGDOMOFSABA_CIV_TEXT_9','Named custom-civilization matchups are conditional mechanical analysis, not tested win rates. All custom civs are human-only and multiplayer is unsupported; these comparisons are for theorycraft or explicitly configured scenarios, not ordinary random AI opponents. General counterplay applies to normal single-player games.[NEWLINE][NEWLINE]FAVOURABLE OPPORTUNITIES[NEWLINE][NEWLINE]Honeycomb Commonwealth: Good River development can proceed without needing a cluster of actually worked Plantation resources.[NEWLINE][NEWLINE]Beyond the Sky: A prepared Spearman-derived defense on suitable Desert can punish an unsupported early mounted attack.[NEWLINE][NEWLINE]THREATS TO RESPECT[NEWLINE][NEWLINE]RomanGladius Network: A protected large Server economy can outgrow modest flat site additions in a long population contest.[NEWLINE][NEWLINE]The Wandering Circus: On terrain without enough qualifying River or Desert sites, a flexible recurring city programme has more opportunities.');
