INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC2_GUIDE_KINGDOMOFSABA_LEADER_BACKGROUND','Choose productive River sites and take the Desert city-centre bonus where the surrounding land can still feed the city. The ability rewards a good settlement, not every city placed beside a visible patch of sand.');
