INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC2_GUIDE_KINGDOMOFSABA_STRATEGY','Choose productive River sites and take the Desert city-centre bonus where the surrounding land can still feed the city. The ability rewards a good settlement, not every city placed beside a visible patch of sand.[NEWLINE][NEWLINE]Scout rivers and the actual city-centre terrain. Prioritize enough food, production and resources over a nominal Desert bonus. Wadi Sentinels help watch and defend suitable dry approaches.[NEWLINE][NEWLINE]Build Cisterns where the active Water Mill requirements permit them. Turn the added food and Gold into citizens, research infrastructure and a workable treasury. Further expansion should be justified by the full site quality.[NEWLINE][NEWLINE]Use the developed population and ordinary science or cultural programme to finish the game. Upgrade defenses when needed; the Sentinel''s specific Desert-defense and Sight additions do not continue through its upgrade.');
