INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC2_GUIDE_KINGDOMOFSABA_LEADER_HEADING_2','Priorities and decisions');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC2_GUIDE_KINGDOMOFSABA_LEADER_TEXT_2','Scout rivers and the actual city-centre terrain. Prioritize enough food, production and resources over a nominal Desert bonus. Wadi Sentinels help watch and defend suitable dry approaches.[NEWLINE][NEWLINE]Build Cisterns where the active Water Mill requirements permit them. Turn the added food and Gold into citizens, research infrastructure and a workable treasury. Further expansion should be justified by the full site quality.[NEWLINE][NEWLINE]Use the developed population and ordinary science or cultural programme to finish the game. Upgrade defenses when needed; the Sentinel''s specific Desert-defense and Sight additions do not continue through its upgrade.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC2_GUIDE_KINGDOMOFSABA_LEADER_HEADING_3','Matchup examples - conditional analysis');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CWC2_GUIDE_KINGDOMOFSABA_LEADER_TEXT_3','Named custom-civilization matchups are conditional mechanical analysis, not tested win rates. All custom civs are human-only and multiplayer is unsupported; these comparisons are for theorycraft or explicitly configured scenarios, not ordinary random AI opponents. General counterplay applies to normal single-player games.[NEWLINE][NEWLINE]FAVOURABLE OPPORTUNITIES[NEWLINE][NEWLINE]Honeycomb Commonwealth: Good River development can proceed without needing a cluster of actually worked Plantation resources.[NEWLINE][NEWLINE]Beyond the Sky: A prepared Spearman-derived defense on suitable Desert can punish an unsupported early mounted attack.[NEWLINE][NEWLINE]THREATS TO RESPECT[NEWLINE][NEWLINE]RomanGladius Network: A protected large Server economy can outgrow modest flat site additions in a long population contest.[NEWLINE][NEWLINE]The Wandering Circus: On terrain without enough qualifying River or Desert sites, a flexible recurring city programme has more opportunities.');
